package gui

// Icons: Lucide artwork (https://lucide.dev, ISC License — Copyright (c)
// Lucide Icons and Contributors; Feather-derived icons (c) Cole Bemis, MIT;
// full text in icons/LICENSE). The SVG sources live in icons_data.go,
// generated by icons/fetch_icons.go; they are parsed on first use and drawn as
// round-capped, round-joined strokes (Gio strokes are always round), so they
// stay crisp at any size and take any colour.

import (
	"image/color"
	"log"
	"sync"

	"gioui.org/f32"
	"gioui.org/layout"
	"gioui.org/op/clip"
	"gioui.org/op/paint"
	"gioui.org/unit"
)

// IconStrokeAt24 is the stroke width of a 24 dp icon (GUI.md: 1.75).
const IconStrokeAt24 = 1.75

// Icon is one vector icon. Draw it with Layout; icons are safe to share.
type Icon struct {
	// Name is the kit name ("home", "check-circle" …).
	Name string
	src  string

	once  sync.Once
	paths []subpath
}

func newIcon(name, src string) *Icon { return &Icon{Name: name, src: src} }

// NewIcon makes an icon from SVG elements in a 24×24 viewBox
// (`<path d="…"/><circle …/>`) — for artwork beyond the built-in set.
func NewIcon(name, svg string) (*Icon, error) {
	ic := newIcon(name, svg)
	p, err := parseSVG(svg)
	if err != nil {
		return nil, err
	}
	ic.once.Do(func() { ic.paths = p })
	return ic, nil
}

func (ic *Icon) load() []subpath {
	ic.once.Do(func() {
		p, err := parseSVG(ic.src)
		if err != nil {
			log.Printf("gui: icon %s: %v", ic.Name, err)
		}
		ic.paths = p
	})
	return ic.paths
}

// IconStroke is the default stroke width for an icon of the given size:
// Lucide's 1.75 at 24 dp, scaled with the icon but never thinner than 1.5 dp
// so small icons stay legible.
func IconStroke(size unit.Dp) unit.Dp {
	return max(1.5, IconStrokeAt24*size/24)
}

// Layout draws the icon as a size×size square in colour c.
func (ic *Icon) Layout(gtx C, size unit.Dp, c color.NRGBA) D {
	return ic.LayoutStroke(gtx, size, IconStroke(size), c)
}

// LayoutStroke is Layout with an explicit stroke width (dp).
func (ic *Icon) LayoutStroke(gtx C, size, stroke unit.Dp, c color.NRGBA) D {
	px := gtx.Dp(size)
	d := D{Size: pt(px, px)}
	if ic == nil || c.A == 0 || px <= 0 {
		return d
	}
	paths := ic.load()
	scale := float32(px) / 24
	w := float32(stroke) * gtx.Metric.PxPerDp
	col := c
	if c.A < 255 {
		// Overlapping strokes of one icon must not double-blend: draw them
		// opaque into one layer and fade the layer.
		defer paint.PushOpacity(gtx.Ops, float32(c.A)/255).Pop()
		col.A = 255
	}
	for _, sp := range paths {
		drawSubpath(gtx, sp, scale, w, col)
	}
	return d
}

// Widget returns a layout.Widget drawing the icon.
func (ic *Icon) Widget(size unit.Dp, c color.NRGBA) layout.Widget {
	return func(gtx C) D { return ic.Layout(gtx, size, c) }
}

// drawSubpath strokes (and fills, for filled dots) one contour. Each contour is
// painted on its own so strokes of different contours never cancel each
// other under the non-zero fill rule.
func drawSubpath(gtx C, sp subpath, scale, width float32, c color.NRGBA) {
	if len(sp.Segs) == 0 {
		return
	}
	// Degenerate contours ("M12 17h.01") are Lucide's dots: a round cap.
	if sp.length() < 0.05 {
		p := sp.Segs[0].P[0].Mul(scale)
		fillCircle(gtx.Ops, p, width/2, c)
		return
	}
	spec := subpathSpec(gtx, sp, scale)
	if sp.Fill {
		paint.FillShape(gtx.Ops, c, clip.Outline{Path: subpathSpec(gtx, sp, scale)}.Op())
	}
	paint.FillShape(gtx.Ops, c, clip.Stroke{Path: spec, Width: width}.Op())
}

func subpathSpec(gtx C, sp subpath, scale float32) clip.PathSpec {
	var p clip.Path
	p.Begin(gtx.Ops)
	s := func(q f32.Point) f32.Point { return q.Mul(scale) }
	for _, g := range sp.Segs {
		switch g.Op {
		case segMove:
			p.MoveTo(s(g.P[0]))
		case segLine:
			p.LineTo(s(g.P[0]))
		case segQuad:
			p.QuadTo(s(g.P[0]), s(g.P[1]))
		case segCube:
			p.CubeTo(s(g.P[0]), s(g.P[1]), s(g.P[2]))
		case segClose:
			p.Close()
		}
	}
	return p.End()
}
